<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Security;

use Civi\Lughauth\Shared\Exception\UnauthorizedException;

/**
 * Checks on an access token that only need its own signed claims (RFC 9068), so any resource
 * server can apply them without the data of the authorization server that issued it.
 *
 * Whether the token was revoked only its issuer knows: a resource server asks it through its
 * introspection endpoint (RFC 7662).
 */
final class AccessTokenClaims
{
    /** Longest time a verified signature is reused before the token is verified again. */
    public const int MAX_CACHE_TTL = 300;

    /**
     * The token is within its validity window: `exp` is required and not past, `nbf` (when
     * present) is not future.
     *
     * @param array<string, mixed> $claims
     * @throws UnauthorizedException
     */
    public static function assertActive(array $claims): void
    {
        $now = time();
        if (!is_numeric($claims['exp'] ?? null) || (int) $claims['exp'] < $now) {
            throw new UnauthorizedException(message: 'The provided JWT is expired.');
        }
        if (is_numeric($claims['nbf'] ?? null) && (int) $claims['nbf'] > $now) {
            throw new UnauthorizedException(message: 'The provided JWT is not ready for use.');
        }
    }

    /**
     * `aud` is present and, when audiences are given, holds at least one of them (RFC 7519 §4.1.3).
     *
     * @param array<string, mixed> $claims
     * @param list<string> $audiences accepted audiences; empty accepts any audience
     * @throws UnauthorizedException
     */
    public static function assertAudience(array $claims, array $audiences): void
    {
        $aud = array_values(array_filter((array) ($claims['aud'] ?? []), 'is_string'));
        if ($aud === [] || ($audiences !== [] && array_intersect($aud, $audiences) === [])) {
            throw new UnauthorizedException(message: 'The audience is not valid.');
        }
    }

    /**
     * The token names who issued it (`iss`) and the tenant it acts in (`tenant`): the identity is
     * built from them, so a token without them is never taken as one of a default tenant.
     *
     * @param array<string, mixed> $claims
     * @throws UnauthorizedException
     */
    public static function assertIssuerAndTenant(array $claims): void
    {
        if (!is_string($claims['iss'] ?? null) || $claims['iss'] === '') {
            throw new UnauthorizedException(message: 'The issuer is not valid.');
        }
        if (!is_string($claims['tenant'] ?? null) || $claims['tenant'] === '') {
            throw new UnauthorizedException(message: 'The tenant is not valid.');
        }
    }
}
